// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;

    function setUp() public { c = new Proxy(); }

    // fuzzed params: address caller (we'll fund & prank), bytes calldata to forward
    function testFuzz_property(address caller, bytes memory data) public {
        // keep caller usable
        caller = vm.addr(uint256(uint160(caller)) | 1); // ensure non-zero address
        vm.deal(caller, 1 ether);

        // Deploy a recorder contract that DOES NOT revert and records that it was called
        Recorder rec = new Recorder();

        // prepare calldata: pass-through any bytes the fuzzer gives; C.forward will call rec with that data
        // make the call as 'caller'
        vm.prank(caller);
        bool ok;
        try c.forward(address(rec), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: when the callee does NOT revert, forward should return (ok==true) and the recorder
        // must have observed the call. The reference satisfies this for all inputs; the mutant that calls
        // address(0) can revert so ok==false and recorder saw nothing. We assert that if c.forward returned
        // successfully then the recorder recorded exactly one call and recorded the same calldata length.
        if (ok) {
            // read recorder's public observations
            assertTrue(rec.callCount() == 1);
            assertTrue(rec.lastDataLength() == data.length);
        } else {
            // If forward reverted, the recorder must not have been called
            assertTrue(rec.callCount() == 0);
        }
    }
}

// Minimal recorder: records number of calls and last msg.data length
contract Recorder {
    uint256 public calls;
    uint256 public lastLen;

    fallback() external payable {
        calls += 1;
        lastLen = msg.data.length;
    }
    receive() external payable {
        calls += 1;
        lastLen = 0;
    }

    // helper getters (auto-generated, but explicit clarity)
    function callCount() external view returns (uint256) { return calls; }
    function lastDataLength() external view returns (uint256) { return lastLen; }
}
